<?php
require_once 'config.php';role_required(['admin','dosen']);
if($_SERVER['REQUEST_METHOD']==='POST'){$nilai=max(0,min(100,(float)$_POST['nilai']));$pdo->prepare("UPDATE pengumpulan SET nilai=?,feedback=?,status='dinilai' WHERE id=?")->execute([$nilai,trim($_POST['feedback']),(int)$_POST['id']]);flash('Nilai dan feedback berhasil disimpan.');redirect('nilai.php');}
$sql="SELECT p.*,u.nama AS mahasiswa,u.nim,t.judul,m.nama AS matkul FROM pengumpulan p JOIN users u ON u.id=p.mahasiswa_id JOIN tugas t ON t.id=p.tugas_id JOIN mata_kuliah m ON m.id=t.mata_kuliah_id";
$args=[];if(user()['role']==='dosen'){$sql.=" WHERE t.dosen_id=?";$args[] = user()['id'];}$sql.=" ORDER BY p.submitted_at DESC";$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();
$page_title='Penilaian';require 'includes/header.php'; ?>
<div class="panel"><h3>Penilaian tugas</h3><p class="muted">Periksa file yang dikumpulkan, berikan nilai 0–100, dan tulis feedback.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Mahasiswa</th><th>Tugas / MK</th><th>File</th><th>Waktu kirim</th><th>Nilai & feedback</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?= e($r['mahasiswa']) ?><div class="muted small"><?= e($r['nim']) ?></div></td><td><?= e($r['judul']) ?><div class="muted small"><?= e($r['matkul']) ?></div></td><td><a href="uploads/<?= e($r['file']) ?>" download>Unduh file</a></td><td><?= date('d/m/Y H:i',strtotime($r['submitted_at'])) ?><div class="small muted"><?= e($r['status']) ?></div></td><td style="min-width:260px"><form method="post" class="d-grid gap-2"><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="number" min="0" max="100" step=".01" name="nilai" value="<?= e($r['nilai']) ?>" class="form-control form-control-sm" placeholder="Nilai"><input name="feedback" value="<?= e($r['feedback']) ?>" class="form-control form-control-sm" placeholder="Feedback"><button class="btn btn-sm btn-primary">Simpan nilai</button></form></td></tr><?php endforeach; ?>
</tbody></table><?php if(!$rows): ?><p class="muted">Belum ada pengumpulan tugas.</p><?php endif; ?></div></div><?php require 'includes/footer.php'; ?>